// Some portions generated by Claude

// @ts-check
const { test, expect } = require('@playwright/test');
const {
	createSeededRepository,
	deleteRepository,
	repositoryPageUrl,
	serverBaseUrl,
	uniqueRepositoryId
} = require('./workbench-test-helpers.js');

// Milestone M5 of .agent/execplans/workbench-app-shell-and-critique-fixes-20260930.md: readable browsing pages.
const REPOSITORY_ID = uniqueRepositoryId('workbench-browsing');
const PRODUCT1 = '<http://www4.wiwiss.fu-berlin.de/bizer/bsbm/v01/instances/dataFromProducer1/Product1>';

test.describe.configure({ mode: 'serial' });

test.beforeAll(async ({ request }) => {
	await createSeededRepository(request, serverBaseUrl(), REPOSITORY_ID);
});

test.afterAll(async ({ request }) => {
	await deleteRepository(request, serverBaseUrl(), REPOSITORY_ID);
});

test('Explore shows the resource card and groups rows by the role of the resource', async ({ page }) => {
	await page.setViewportSize({ width: 1440, height: 900 });
	await page.goto(`${repositoryPageUrl(REPOSITORY_ID, 'explore')}?resource=${encodeURIComponent(PRODUCT1)}`,
		{ waitUntil: 'networkidle' });
	await expect(page.locator('#explore-resource-card h2')).toHaveText('turgescence retrospection');
	const outgoing = page.locator('section.explore-group[data-explore-role="outgoing"]');
	await expect(outgoing.locator('h3')).toContainText('Outgoing');
	await expect(outgoing.locator('tbody tr').first().locator('td').first()).toHaveText(/^[\w-]+:[\w-]+$/);
	const dateCell = outgoing.locator('td').filter({ has: page.locator('.rdf-datatype', { hasText: 'xsd:date' }) }).first();
	await expect(dateCell).toContainText('xsd:date');
	await page.locator('#explore-result-options-toggle').click();
	await page.locator('label[for="explore-show-datatypes"]').click();
	await expect.poll(() => dateCell.innerText()).not.toContain('xsd:date');
});
